update public.municipality_contacts
set address = coalesce(address,'Townhall, Mahaveer Vacant Road, Gandhi Nagar, Tumakuru, Karnataka 572102, India'),
    services = case when cardinality(services)=0 then array['Municipal civic office contact','Official address and website published by Tumakuru District Administration']::text[] else services end,
    verified_at = coalesce(verified_at, date '2026-11-25'), is_active = true, updated_at = now()
where district = 'Tumakuru' and office_name = 'Tumakuru City Corporation'
  and source_url = 'https://tumkur.nic.in/en/public-utility/tumkur-city-corporation/';

