insert into public.municipality_contacts(district,taluk,jurisdiction,office_name,contact_person,phone,email,address,services,source_url,verified_at,verified_by,is_active)
select c.district,c.taluk,c.jurisdiction,c.office_name,c.contact_person,c.phone,c.email,c.address,c.services,c.source_url,date '2026-11-25',null,true
from contacts c
where not exists (select 1 from public.municipality_contacts existing where existing.district=c.district and existing.office_name=c.office_name);
